import subprocess,unicodedata
files = subprocess.run(['git','ls-files'],capture_output=True,text=True).stdout.split('\n')
hits={}
for f in files:
    if not f: continue
    try: t=open(f,encoding='utf-8').read()
    except Exception: continue
    t=unicodedata.normalize('NFC',t)
    n=t.count('Dalén')+t.count('Dalen')
    if n:
        i=max(t.find('Dalén'),t.find('Dalen'))
        hits[f]=(n,t[max(0,i-60):i+40].replace('\n',' '))
print(f"tracked files still carrying the name: {len(hits)}")
for f,(n,ctx) in hits.items(): print(f"  {f} ({n})\n     …{ctx}…")
